{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 조례상 야간 주차장 확보율 65%일 때 시장이 개선지구 지정을 권고할 수 있는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 주차장 설치 및 관리 조례 제4조제1항에 따르면 시장은 야간시간대의 수급 실태조사를 고려한 주차장확보율이 70% 미만인 지역을 주차환경개선지구로 지정할 것을 구청장에게 권고할 수 있다. 야간 주차장 확보율 65%는 70% 미만에 해당하므로 시장이 개선지구 지정을 권고할 수 있다.",
          "b_ids": "주차장:제4조제1항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "개선지구 지정 권고에 따라 지정된 곳의 학교운동장 야간 개방에 예산을 우선 지원할 수 있는지 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "서울특별시 주차장 설치 및 관리 조례 제4조제2항은 시장이 제1항의 권고에 따라 구청장이 지정한 주차환경개선지구에 대하여 학교운동장 야간개방 사업 등 해당 사업예산을 우선하여 지원할 수 있다고 규정한다. 따라서 개선지구 지정 권고에 따라 지정된 곳이라면 학교운동장 야간 개방에 예산을 우선 지원할 수 있다.",
          "b_ids": "주차장:제4조제2항, 주차장:제4조제2항제2호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
